import sys


def solve() -> None:
    data = sys.stdin.read().split()
    pos = 0
    H = int(data[pos]); pos += 1
    W = int(data[pos]); pos += 1
    k = int(data[pos]); pos += 1

    # 读取初始网格 (每行 W 个字符, 只含 '.' 与 '#')
    grid = []
    for _ in range(H):
        row = data[pos]; pos += 1
        grid.append([1 if ch == '#' else 0 for ch in row])

    # 同时按 8 邻域模拟 k 代; 网格外视为死格
    for _ in range(k):
        nxt = [[0] * W for _ in range(H)]
        for r in range(H):
            for c in range(W):
                # 统计 8 邻域活细胞数 (越界跳过 => 死格)
                n = 0
                for dr in (-1, 0, 1):
                    for dc in (-1, 0, 1):
                        if dr == 0 and dc == 0:
                            continue
                        rr = r + dr
                        cc = c + dc
                        if 0 <= rr < H and 0 <= cc < W and grid[rr][cc]:
                            n += 1
                if grid[r][c]:
                    # 活细胞: 邻居 2 或 3 存活, 否则死亡
                    nxt[r][c] = 1 if (n == 2 or n == 3) else 0
                else:
                    # 死细胞: 邻居恰为 3 复活
                    nxt[r][c] = 1 if n == 3 else 0
        grid = nxt

    out = []
    for r in range(H):
        out.append(''.join('#' if v else '.' for v in grid[r]))
    sys.stdout.write('\n'.join(out) + '\n')


if __name__ == '__main__':
    solve()
```

要点: 使用 `split()` 读取全部 token(避免行末换行/空白干扰), 逐元素按“先算全网格再整体替换”实现**同时**更新, 越界坐标直接跳过等价于死格。输出严格仅网格本身。
